{"hypotheses": [
  {
    "name": "Supply Chain Shock Absorbers",
    "mechanism": "Combining the customer and supplier momentum factors exploits firms resilient to supply chain disruptions. Firms excelling in both suggest robust supply-demand linkages, amplifying their ability to weather exogenous shocks. The interaction captures spillover and persistence effects not present in either channel alone.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "iomom_cust"},
        {"weight": 1.0, "primitive": "iomom_supp"},
        {"weight": -0.5, "primitive": "BetaTailRisk"}
      ],
      "regime": "VIX_ABOVE_TRAILING_MEDIAN",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "VIX_ABOVE_TRAILING_MEDIAN", "direction": "higher"},
      {"type": "size_segment", "segment": "large", "direction": "stronger"},
      {"type": "correlation", "primitive": "Mom12m", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.90,
    "expected_decay_half_life_months": 24
  },
  {
    "name": "Intangible Efficiency Spread",
    "mechanism": "This composite captures firms excelling in both brand investments and R&D efficiency, but penalizes those that only accumulate intangible assets without profitability. The interaction should pick up firms converting intangibles into actual business advantages, not just spending.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "BrandInvest"},
        {"weight": 0.5, "primitive": "RDAbility"},
        {"weight": -1.0, "primitive": "IntanBM"}
      ],
      "regime": null,
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "international", "region": "developed_ex_us", "direction": "same_sign"},
      {"type": "correlation", "primitive": "CF", "bound": "below", "threshold": 0.3},
      {"type": "size_segment", "segment": "large", "direction": "stronger"}
    ],
    "expected_annualized_sharpe": 0.70,
    "expected_decay_half_life_months": 18
  },
  {
    "name": "Procyclical Governance Premium",
    "mechanism": "Firms with strong governance and high payout yields exhibit amplified procyclical returns when credit markets are loose. The combination should outperform each component when economic confidence is high and capital allocation is both disciplined and shareholder-friendly.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "Governance"},
        {"weight": 1.0, "primitive": "PayoutYield"},
        {"weight": 0.5, "primitive": "NetPayoutYield"}
      ],
      "regime": "TERM_SPREAD_POSITIVE",
      "vol_target": false
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "TERM_SPREAD_POSITIVE", "direction": "higher"},
      {"type": "subperiod_consistency"},
      {"type": "correlation", "primitive": "BM", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.65,
    "expected_decay_half_life_months": 30
  },
  {
    "name": "Contrarian Analyst Revision-Dispersion",
    "mechanism": "Firms with rising EPS forecast revisions but high forecast dispersion are often overlooked due to perceived risk. This composite bets on positive revisions when the analyst base is divided, exploiting delayed consensus formation.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "AnalystRevision"},
        {"weight": 1.0, "primitive": "EarningsForecastDisparity"},
        {"weight": -0.5, "primitive": "ForecastDispersion"}
      ],
      "regime": "MKT_TRAILING_12M_UP",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "MKT_TRAILING_12M_UP", "direction": "higher"},
      {"type": "size_segment", "segment": "small", "direction": "stronger"},
      {"type": "correlation", "primitive": "AnalystValue", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.75,
    "expected_decay_half_life_months": 20
  },
  {
    "name": "Inventory-Cycle Risk Aversion",
    "mechanism": "Combining inventory growth, Amihud illiquidity, and short-term reversal, this composite bets against firms with rising inventories and illiquidity, except when mean reversion dominates. The interaction captures inventory-cycle risk mispricing amplified by liquidity constraints.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "InvGrowth"},
        {"weight": 0.5, "primitive": "Illiquidity"},
        {"weight": -1.0, "primitive": "STreversal"}
      ],
      "regime": "VIX_ABOVE_TRAILING_MEDIAN",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "VIX_ABOVE_TRAILING_MEDIAN", "direction": "higher"},
      {"type": "size_segment", "segment": "micro", "direction": "stronger"},
      {"type": "correlation", "primitive": "AssetGrowth", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.80,
    "expected_decay_half_life_months": 12
  },
  {
    "name": "IPO Posture Paradox",
    "mechanism": "Firms recently public (young IPO age) but with high organizational capital and minimal short interest balance novelty and embedded know-how with skepticism. The composite exploits cases where market underappreciates operational readiness amid debut uncertainty.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "AgeIPO"},
        {"weight": 1.0, "primitive": "OrgCap"},
        {"weight": -1.0, "primitive": "ShortInterest"}
      ],
      "regime": null,
      "vol_target": false
    },
    "auxiliary_predictions": [
      {"type": "size_segment", "segment": "small", "direction": "stronger"},
      {"type": "international", "region": "emerging", "direction": "same_sign"},
      {"type": "subperiod_consistency"}
    ],
    "expected_annualized_sharpe": 0.60,
    "expected_decay_half_life_months": 36
  },
  {
    "name": "Capital Discipline under Stress",
    "mechanism": "Firms with high cash productivity and low composite equity issuance (i.e., returning capital rather than raising it) outperform specifically during falling markets. The discipline to produce cash and avoid dilutive actions signals resilience.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "CashProd"},
        {"weight": -1.0, "primitive": "CompEquIss"},
        {"weight": 0.5, "primitive": "DelEqu"}
      ],
      "regime": "MKT_TRAILING_12M_DOWN",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "MKT_TRAILING_12M_DOWN", "direction": "higher"},
      {"type": "size_segment", "segment": "mega", "direction": "weaker"},
      {"type": "correlation", "primitive": "CBOperProf", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.80,
    "expected_decay_half_life_months": 16
  },
  {
    "name": "Smirk-Skew Volatility Mispricing",
    "mechanism": "Combining the volatility smirk and realized skewness factors, this composite arbitrages option market mispricings related to tail risk that are not captured by linear volatility strategies. It bets on stocks with extreme implied skew but low realized skewness, exploiting behavioral risk misestimation.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "skew1"},
        {"weight": -1.0, "primitive": "ReturnSkew"},
        {"weight": 0.5, "primitive": "SmileSlope"}
      ],
      "regime": null,
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "VIX_BELOW_TRAILING_MEDIAN", "direction": "higher"},
      {"type": "size_segment", "segment": "large", "direction": "stronger"},
      {"type": "correlation", "primitive": "RealizedVol", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.70,
    "expected_decay_half_life_months": 10
  }
]}
